1	// sc4sap:program-to-manual — builds the end-user manual (one self-contained HTML).
2	//
3	// INPUT  manual.json written by sap-writer (schema: skills/program-to-manual/manual-schema.md)
4	// OUTPUT <out-dir>/<PROGRAM>-v<version>-<lang>.html
5	//        <out-dir>/<PROGRAM>-<lang>.history.json   (revision history, one entry per version)
6	//        <out-dir>/_src/<PROGRAM>-v<version>-<lang>.manual.json   (the input, for regeneration)
7	//
8	// Screens are drawn with the program-to-spec renderer (screen-image-renderer.mjs)
9	// and inlined as SVG — no headless browser is needed. Each step's callouts name
10	// the element they point at by its data-anchor key (sel:P_WERKS, col:MATNR,
11	// pai:SEND, …); the page script draws the numbered marks, and this builder
12	// warns about any key the drawn screen does not contain.
13	//
14	// CLI
15	//   node build-manual.mjs <manual.json> [--out-dir DIR] [--same-version] [--major]
16	//     --same-version  rebuild the latest version in place (review loop) instead of adding one
17	//     --major         next version is <major+1>.0 instead of <major>.<minor+1>
18	//   Prints warnings, then a JSON manifest { html, version, history, source, warnings }.
19	//   node build-manual.mjs --import <edited.html> <manual.json>
20	//     writes the manual.json a user saved from the page's edit mode (backs up the old one as .bak)
21	
22	import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
23	import { join, resolve } from 'node:path';
24	import { fileURLToPath } from 'node:url';
25	import {
26	  renderSelectionScreenSVG, renderAlvScreenSVG, renderFlowchartSVG, renderProcessFlowSVG, selectionSchemaWarnings,
27	} from '../spec/screen-image-renderer.mjs';
28	import { looksLikeEnglishProse } from '../spec/build-spec.mjs';
29	import { resolveArtifactBase, readScreenTheme } from '../lib/profile-resolve.mjs';
30	import { readManualConfig } from './manual-config.mjs';
31	import { labelsFor, STYLE, SCRIPT } from './manual-page.mjs';
32	import { renderExcelSheetSVG } from './excel-sheet-svg.mjs';
33	import { EDITOR_STYLE, EDITOR_SCRIPT, QUILL_CSS, QUILL_JS, editorLabels } from './manual-editor.mjs';
34	
35	/** JSON inside a <script> element: nothing in it may close the element. */
36	const LS = String.fromCharCode(0x2028), PS = String.fromCharCode(0x2029);
37	const embedJson = (v) => JSON.stringify(v).replace(/</g, '\\u003c').split(LS).join('\\u2028').split(PS).join('\\u2029');
38	
39	const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
40	const unesc = (s) => String(s).replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
41	/**
42	 * Escaped text with **bold**, ==highlight==, `code`, line breaks and "- " bullet lines —
43	 * the same markup the page's edit mode writes (manual-editor.mjs).
44	 */
45	const inline = (s) => String(s ?? '').split(/\r?\n/).map((line) => {
46	  const bullet = line.startsWith('- ');
47	  const html = esc(bullet ? line.slice(2) : line)
48	    .replace(/`([^`]+)`/g, '<code>$1</code>')
49	    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
50	    .replace(/==([^=]+)==/g, '<mark class="em">$1</mark>');
51	  return bullet ? `<span class="bl">${html}</span>` : html;
52	}).join('<br>');
53	const arr = (x) => (Array.isArray(x) ? x.filter(v => v != null) : []);
54	const slug = (s) => String(s).replace(/[^A-Za-z0-9_-]+/g, '-');
55	const today = () => {
56	  const d = new Date();
57	  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
58	};
59	
60	// ── Screens ─────────────────────────────────────────────────────────────
61	
62	const isSelection = (key, spec) => key === 'selection' || spec?.kind === 'selection'
63	  || (spec?.kind !== 'excel' && !spec?.columns && !spec?.panes && (Array.isArray(spec?.blocks) || Array.isArray(spec?.fields)));
64	
65	/** Selection spec with a step's input values: param/range defaults, checkbox ticks, the chosen radio. */
66	export function applySelectionValues(selection, values) {
67	  if (!values || typeof values !== 'object') return selection;
68	  const has = (n) => n && Object.prototype.hasOwnProperty.call(values, n);
69	  const item = (it) => {
70	    if (!it || typeof it !== 'object') return it;
71	    const t = it.type || (it.range ? 'range' : 'param');
72	    if (t === 'frame') return { ...it, items: arr(it.items).map(item) };
73	    if (t === 'radioGroup' && arr(it.options).some(o => has(o.name) && values[o.name])) {
74	      return { ...it, options: arr(it.options).map(o => ({ ...o, selected: Boolean(has(o.name) && values[o.name]) })) };
75	    }
76	    if (t === 'checkboxGroup') {
77	      return { ...it, options: arr(it.options).map(o => (has(o.name) ? { ...o, checked: Boolean(values[o.name]) } : o)) };
78	    }
79	    if (!has(it.name)) return it;
80	    const v = values[it.name];
81	    if (t === 'checkbox') return { ...it, checked: Boolean(v) };
82	    if (Array.isArray(v)) return { ...it, default: v[0] ?? '', defaultHigh: v[1] ?? '' };
83	    return { ...it, default: v };
84	  };
85	  return {
86	    ...selection,
87	    blocks: selection.blocks ? arr(selection.blocks).map(b => ({ ...b, items: arr(b.items).map(item) })) : selection.blocks,
88	    fields: selection.fields ? arr(selection.fields).map(item) : selection.fields,
89	    optionFields: selection.optionFields ? arr(selection.optionFields).map(f => item({ type: 'checkbox', ...f })) : selection.optionFields,
90	  };
91	}
92	
93	/** Inline SVG without the XML prolog, never drawn wider than its natural size (a small popup stays small). */
94	const fitSvg = (svg) => String(svg).replace(/^<\?xml[^>]*\?>\s*/, '')
95	  .replace(/^<svg([^>]*?)\swidth="(\d+)"/, (m, attrs, w) => `<svg${attrs} width="${w}" style="max-width:${w}px"`);
96	
97	/** A screenshot the user put in place of the drawn screen (edit mode): { src: data URI, width, height }. */
98	function imageSvg(img) {
99	  const w = Math.round(Number(img.width) || 1200), h = Math.round(Number(img.height) || 700);
100	  return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><image href="${esc(img.src)}" x="0" y="0" width="${w}" height="${h}"/></svg>`;
101	}
102	
103	export function renderStepScreen(manual, step) {
104	  if (step?.image?.src) return { key: 'image', image: true, svg: fitSvg(imageSvg(step.image)) };
105	  const key = step?.screen;
106	  if (!key) return null;
107	  const base = manual.screens?.[key];
108	  if (!base) return { key, error: `screen "${key}" is not in manual.screens` };
109	  const spec = { ...base, ...(step.patch && typeof step.patch === 'object' ? step.patch : {}) };
110	  const lang = manual.lang || 'ko';
111	  const svg = spec.kind === 'excel' ? renderExcelSheetSVG(spec)
112	    : isSelection(key, spec)
113	    ? renderSelectionScreenSVG({ ...applySelectionValues(spec, step.values), lang, theme: manual.theme })
114	    : renderAlvScreenSVG(spec, { lang, theme: manual.theme });
115	  return { key, svg: fitSvg(svg) };
116	}
117	
118	export const svgAnchors = (svg) => [...String(svg).matchAll(/data-anchor="([^"]*)"/g)].map(m => unesc(m[1]));
119	
120	function anchorCount(anchors, anchor) {
121	  // Only a trailing #<digits> picks the nth match — labels may contain '#' themselves.
122	  const [, key, nth] = /^([\s\S]*?)(?:#(\d+))?$/.exec(String(anchor));
123	  return anchors.filter(a => a === key).length >= (Number(nth) || 1);
124	}
125	
126	// ── Checks ──────────────────────────────────────────────────────────────
127	
128	export function manualWarnings(manual) {
129	  const warns = [];
130	  const L = manual.lang || 'ko';
131	  if (!manual.program) warns.push('manual.program is missing');
132	  if (!arr(manual.scenarios).length) warns.push('manual.scenarios is empty — a manual needs at least one scenario');
133	  for (const [key, spec] of Object.entries(manual.screens || {})) {
134	    if (isSelection(key, spec)) for (const w of selectionSchemaWarnings(spec)) warns.push(`screens.${key}: ${w}`);
135	  }
136	  arr(manual.scenarios).forEach((sc, si) => {
137	    arr(sc.steps).forEach((st, ti) => {
138	      const where = `scenario ${si + 1} step ${ti + 1}`;
139	      const drawn = renderStepScreen(manual, st);
140	      if (drawn?.error) { warns.push(`${where}: ${drawn.error}`); return; }
141	      const anchors = drawn ? svgAnchors(drawn.svg) : [];
142	      arr(st.callouts).forEach((c, ci) => {
143	        if (!c.anchor || drawn?.image) return; // a screenshot has no anchors — its marks use `pos`
144	        if (!drawn) warns.push(`${where} callout ${ci + 1}: anchor "${c.anchor}" but the step has no screen`);
145	        else if (!anchorCount(anchors, c.anchor)) {
146	          warns.push(`${where} callout ${ci + 1}: anchor "${c.anchor}" is not on screen "${drawn.key}" — available: ${[...new Set(anchors)].join(', ') || '(none)'}`);
147	        }
148	      });
149	    });
150	    if (!arr(sc.checkpoints).length) warns.push(`scenario ${si + 1} "${sc.title || ''}" has no checkpoints — derive them from the source validations or confirm there are none`);
151	  });
152	  if (L === 'ko' || L === 'ja') {
153	    const prose = [];
154	    const add = (path, v) => { if (v && looksLikeEnglishProse(v)) prose.push(`${path}: ${JSON.stringify(String(v).slice(0, 70))}`); };
155	    const intro = manual.intro || {};
156	    ['purpose', 'background', 'users'].forEach(k => add(`intro.${k}`, intro[k]));
157	    arr(intro.businessRules).forEach((r, i) => add(`intro.businessRules[${i}]`, r));
158	    arr(manual.scenarios).forEach((sc, si) => {
159	      add(`scenarios[${si}].title`, sc.title); add(`scenarios[${si}].goal`, sc.goal);
160	      arr(sc.steps).forEach((st, ti) => {
161	        ['title', 'note', 'result'].forEach(k => add(`scenarios[${si}].steps[${ti}].${k}`, st[k]));
162	        arr(st.callouts).forEach((c, ci) => {
163	          add(`scenarios[${si}].steps[${ti}].callouts[${ci}]`, c.text);
164	          arr(c.details).forEach((d, di) => add(`scenarios[${si}].steps[${ti}].callouts[${ci}].details[${di}]`, d));
165	        });
166	      });
167	      arr(sc.checkpoints).forEach((c, ci) => add(`scenarios[${si}].checkpoints[${ci}]`, typeof c === 'string' ? c : c?.text));
168	    });
169	    arr(manual.messages).forEach((m, i) => { add(`messages[${i}].cause`, m.cause); add(`messages[${i}].action`, m.action); });
170	    arr(manual.glossary).forEach((g, i) => add(`glossary[${i}].description`, g.description));
171	    for (const k of ['selection', 'output']) arr(manual.fields?.[k]).forEach((f, i) => add(`fields.${k}[${i}].description`, f.description));
172	    if (prose.length) warns.push(`LANGUAGE MIX (lang=${L}) — translate:\n    · ${prose.slice(0, 30).join('\n    · ')}${prose.length > 30 ? `\n    · … (${prose.length - 30} more)` : ''}`);
173	  }
174	  return warns;
175	}
176	
177	// ── Revision history ────────────────────────────────────────────────────
178	
179	export function nextVersion(history, { sameVersion = false, major = false } = {}) {
180	  const last = arr(history?.versions).at(-1)?.version;
181	  if (!last) return '1.0';
182	  if (sameVersion) return last;
183	  const [ma, mi] = String(last).split('.').map(n => Number(n) || 0);
184	  return major ? `${ma + 1}.0` : `${ma}.${mi + 1}`;
185	}
186	
187	// ── Page ────────────────────────────────────────────────────────────────
188	
189	function table(head, rows) {
190	  if (!rows.length) return '';
191	  return `<table><thead><tr>${head.map(h => `<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map(c => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
192	}
193	
194	/**
195	 * A table whose rows the edit mode can add and delete: the table names the array it
196	 * shows (data-array) and its columns (data-cols: key + kind), each row is one item of
197	 * that array (data-row), each cell names its key in the item — data-c for text,
198	 * data-flag for a ● yes/no column. Column `keys` lists fallbacks (header, then label).
199	 */
200	function editTable(arrayPath, cols, items) {
201	  if (!items.length) return '';
202	  const cell = (col, item) => {
203	    const key = col.keys.find(k => item[k] != null) ?? col.keys[0];
204	    if (col.kind === 'flag') return `<td data-flag="${esc(key)}">${item[key] ? '●' : ''}</td>`;
205	    const span = `<span data-c="${esc(key)}">${inline(item[key] ?? '')}</span>`;
206	    return `<td>${col.kind === 'code' ? `<code>${span}</code>` : span}</td>`;
207	  };
208	  const spec = cols.map(c => ({ key: c.keys[0], kind: c.kind || 'text' }));
209	  return `<table class="ed-table" data-array="${esc(arrayPath)}" data-cols="${esc(JSON.stringify(spec))}">`
210	    + `<thead><tr>${cols.map(c => `<th>${esc(c.head)}</th>`).join('')}</tr></thead>`
211	    + `<tbody>${items.map((it, i) => `<tr data-row="${i}">${cols.map(c => cell(c, it)).join('')}</tr>`).join('')}</tbody></table>`;
212	}
213	
214	// Editable text carries its manual.json path so the page's edit mode (manual-editor.mjs)
215	// can write changes back: data-p = absolute path, data-k = path inside the step.
216	const ed = (path, s, attr = 'data-p') => `<span ${attr}="${esc(path)}">${inline(s)}</span>`;
217	const stepEd = (key, s) => ed(key, s, 'data-k');
218	
219	/** One callout's mark data for the page script: [number, anchor, offset, pos]. */
220	const markOf = (c, i) => [i + 1, c.anchor || '', Array.isArray(c.offset) ? c.offset : null, Array.isArray(c.pos) ? c.pos : null];
221	
222	function calloutsHtml(callouts) {
223	  return `<ol class="callouts">${callouts.map((c, i) => `<li data-ci="${i}"><span class="num">${i + 1}</span><div>${stepEd(`callouts.${i}.text`, c.text)}`
224	    + `${arr(c.details).length ? `<ul>${arr(c.details).map((d, di) => `<li>${stepEd(`callouts.${i}.details.${di}`, d)}</li>`).join('')}</ul>` : ''}</div></li>`).join('')}</ol>`;
225	}
226	
227	function stepHtml(manual, sc, si, st, ti, T, secNo) {
228	  const drawn = renderStepScreen(manual, st);
229	  const callouts = arr(st.callouts);
230	  const marks = callouts.map(markOf).filter(m => m[1] || m[3]);
231	  const figure = drawn?.svg
232	    ? `<figure class="screen"${marks.length ? ` data-callouts="${esc(JSON.stringify(marks))}"` : ''}${st.image ? ' data-image=""' : ''}>${drawn.svg}`
233	      + `<figcaption>${stepEd('caption', st.caption || '')}</figcaption></figure>`
234	    : '';
235	  const tcode = st.tcode || sc.tcode || manual.tcode || manual.program;
236	  const head = `<table class="step-head"><tbody>`
237	    + `<tr><th>${esc(T.transaction)}</th><td>${esc(`${secNo}-${si + 1}`)} <span class="sc-title">${inline(sc.title)}</span></td></tr>`
238	    + `<tr><th>${esc(T.description)}</th><td><span class="stepno">${ti + 1}</span>. ${stepEd('title', st.title)}</td></tr>`
239	    + `<tr><th>${esc(T.tcode)}</th><td><code>${esc(tcode)}</code>${manual.cbo === false ? '' : ` <span class="flag">${esc(T.cbo)}</span>`}</td></tr>`
240	    + (manual.menuPath ? `<tr><th>${esc(T.menuPath)}</th><td>${inline(manual.menuPath)}</td></tr>` : '')
241	    + `</tbody></table>`;
242	  const note = `<p class="step-note"${st.note ? '' : ' hidden'}>${stepEd('note', st.note || '')}</p>`
243	    + `<p class="step-note"${st.result ? '' : ' hidden'}><strong>${esc(T.result)}:</strong> ${stepEd('result', st.result || '')}</p>`;
244	  return `<article class="step${ti > 0 ? ' page-break' : ''}" id="s${si + 1}-${ti + 1}" data-si="${si}" data-ti="${ti}">${head}`
245	    + `<div class="step-body${figure ? ' has-screen' : ''}">${figure}<div>${calloutsHtml(callouts)}${note}</div></div></article>`;
246	}
247	
248	export function renderManualHtml(manual, { version, date, config = {}, history = [] }) {
249	  const T = labelsFor(manual.lang);
250	  const intro = manual.intro || {};
251	  const flagged = new Set(arr(intro.unverified));
252	  const mark = (s) => (flagged.has(s) ? ` <span class="flag">${esc(T.unverified)}</span>` : '');
253	  const title = manual.title || manual.program;
254	  const toc = [];
255	  const sec = [];
256	
257	  // Cover
258	  const meta = [
259	    [T.program, `<code>${esc(manual.program)}</code>`], [T.tcode, `<code>${esc(manual.tcode || manual.program)}</code>`],
260	    [T.version, `v${esc(version)}`], [T.date, esc(date)],
261	    config.team && [T.team, esc(config.team)], config.author && [T.author, esc(config.author)],
262	  ].filter(Boolean);
263	  sec.push(`<section class="cover" id="cover"><div class="kicker">${esc(manual.module ? `${manual.module} · ` : '')}${esc(T.manual)}</div><h1>${ed('title', title)}</h1>`
264	    + `<dl class="meta">${meta.map(([k, v]) => `<dt>${esc(k)}</dt><dd>${v}</dd>`).join('')}</dl>`
265	    + (config.company ? `<div class="kicker">${esc(config.company)}</div>` : '') + `</section>`);
266	
267	  // Revision history
268	  toc.push(['revision', T.revision]);
269	  sec.push(`<section id="revision" class="page-break"><h2>${esc(T.revision)}</h2>${table([T.version, T.date, T.author, T.change],
270	    history.map(h => [`v${esc(h.version)}`, esc(h.date), esc(h.author || ''), inline(h.note || '')]))}</section>`);
271	
272	  // 1. Introduction
273	  let n = 1;
274	  const introParts = [];
275	  if (intro.purpose) introParts.push(`<h3>${esc(T.purpose)}</h3><p>${ed('intro.purpose', intro.purpose)}${mark(intro.purpose)}</p>`);
276	  if (intro.background) introParts.push(`<h3>${esc(T.background)}</h3><p>${ed('intro.background', intro.background)}${mark(intro.background)}</p>`);
277	  if (arr(intro.businessRules).length) introParts.push(`<h3>${esc(T.rules)}</h3><ul>${arr(intro.businessRules).map((r, i) => `<li>${ed(`intro.businessRules.${i}`, r)}${mark(r)}</li>`).join('')}</ul>`);
278	  if (intro.users) introParts.push(`<h3>${esc(T.users)}</h3><p>${ed('intro.users', intro.users)}${mark(intro.users)}</p>`);
279	  const pf = manual.processFlow;
280	  const pfSvg = pf && !Array.isArray(pf) && Array.isArray(pf.nodes) ? renderFlowchartSVG(pf, { lang: manual.lang })
281	    : Array.isArray(pf) && pf.length ? renderProcessFlowSVG(pf, { lang: manual.lang, orientation: 'horizontal' }) : '';
282	  if (pfSvg) introParts.push(`<h3>${esc(T.flow)}</h3><figure class="screen">${fitSvg(pfSvg)}</figure>`);
283	  toc.push(['intro', `${n}. ${T.intro}`]);
284	  sec.push(`<section id="intro" class="page-break"><h2>${n}. ${esc(T.intro)}</h2>${introParts.join('')}</section>`);
285	
286	  // 2. Scenarios
287	  n += 1;
288	  const scToc = [];
289	  const scHtml = arr(manual.scenarios).map((sc, si) => {
290	    scToc.push([`s${si + 1}`, `${n}-${si + 1} ${sc.title || ''}`]);
291	    const steps = arr(sc.steps).map((st, ti) => stepHtml(manual, sc, si, st, ti, T, n)).join('');
292	    const cps = arr(sc.checkpoints).map((c, ci) => (typeof c === 'string' ? { text: c, path: `${ci}` } : { ...c, path: `${ci}.text` })).filter(c => c?.text);
293	    const cpHtml = cps.length
294	      ? `<aside class="checkpoints"><h4>${esc(T.checkpoints)}</h4><ul>${cps.map(c => `<li>${ed(`scenarios.${si}.checkpoints.${c.path}`, c.text)}${c.source ? ` <span class="src">(${esc(c.source)})</span>` : ''}</li>`).join('')}</ul></aside>`
295	      : '';
296	    return `<section id="s${si + 1}" data-si="${si}"${si > 0 ? ' class="page-break"' : ''}><h3>${n}-${si + 1} ${ed(`scenarios.${si}.title`, sc.title)}</h3>`
297	      + `${sc.goal ? `<p class="scenario-goal">${esc(T.goal)}: ${ed(`scenarios.${si}.goal`, sc.goal)}</p>` : ''}${steps}${cpHtml}</section>`;
298	  }).join('');
299	  toc.push(['scenarios', `${n}. ${T.scenarios}`, scToc]);
300	  sec.push(`<section id="scenarios" class="page-break"><h2>${n}. ${esc(T.scenarios)}</h2>${scHtml}</section>`);
301	
302	  // 3. Fields
303	  const selF = arr(manual.fields?.selection), outF = arr(manual.fields?.output);
304	  if (selF.length || outF.length) {
305	    n += 1;
306	    toc.push(['fields', `${n}. ${T.fields}`]);
307	    sec.push(`<section id="fields" class="page-break"><h2>${n}. ${esc(T.fields)}</h2>`
308	      + (selF.length ? `<h3>${esc(T.selFields)}</h3>${editTable('fields.selection', [
309	        { head: T.field, keys: ['name'], kind: 'code' }, { head: T.label, keys: ['label'] },
310	        { head: T.required, keys: ['required'], kind: 'flag' }, { head: T.f4, keys: ['f4'], kind: 'flag' },
311	        { head: T.example, keys: ['example'] }, { head: T.meaning, keys: ['description'] }], selF)}` : '')
312	      + (outF.length ? `<h3>${esc(T.outFields)}</h3>${editTable('fields.output', [
313	        { head: T.field, keys: ['name'], kind: 'code' }, { head: T.label, keys: ['header', 'label'] },
314	        { head: T.meaning, keys: ['description'] }], outF)}` : '')
315	      + `</section>`);
316	  }
317	
318	  // 4. Messages
319	  const msgs = arr(manual.messages);
320	  if (msgs.length) {
321	    n += 1;
322	    toc.push(['messages', `${n}. ${T.messages}`]);
323	    sec.push(`<section id="messages" class="page-break"><h2>${n}. ${esc(T.messages)}</h2>${editTable('messages', [
324	      { head: T.code, keys: ['code'], kind: 'code' }, { head: T.msgType, keys: ['type'] }, { head: T.text, keys: ['text'] },
325	      { head: T.cause, keys: ['cause'] }, { head: T.action, keys: ['action'] }], msgs)}</section>`);
326	  }
327	
328	  // 5. Glossary
329	  const gl = arr(manual.glossary);
330	  if (gl.length) {
331	    n += 1;
332	    toc.push(['glossary', `${n}. ${T.glossary}`]);
333	    sec.push(`<section id="glossary" class="page-break"><h2>${n}. ${esc(T.glossary)}</h2>${editTable('glossary', [
334	      { head: T.term, keys: ['term'] }, { head: T.meaning, keys: ['description'] }], gl)}</section>`);
335	  }
336	
337	  const tocHtml = `<ol>${toc.map(([id, label, kids]) => `<li><a href="#${id}">${esc(label)}</a>${kids?.length ? `<ol>${kids.map(([k, l]) => `<li><a href="#${k}">${esc(l)}</a></li>`).join('')}</ol>` : ''}</li>`).join('')}</ol>`;
338	  const footer = [config.company, config.confidentiality].filter(Boolean).join(' · ');
339	  return `<!doctype html>
340	<html lang="${esc(manual.lang || 'ko')}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
341	<title>${esc(title)} — ${esc(T.manual)} v${esc(version)}</title>
342	<style>${STYLE}${QUILL_CSS}${EDITOR_STYLE}</style></head>
343	<body>
344	<header class="topbar"><span class="t">${esc(title)} · <code>${esc(manual.program)}</code> · v${esc(version)}</span><span class="ed-bar" id="ed-bar" hidden></span><button id="edit-btn" type="button">${esc(editorLabels(manual.lang).edit)}</button><button id="print-btn" type="button">${esc(T.print)}</button><button id="theme-btn" type="button">${esc(T.theme)}</button></header>
345	<div class="layout"><nav class="toc" aria-label="${esc(T.contents)}">${tocHtml}</nav><main>
346	${sec.join('\n')}
347	<footer class="doc-end"><strong>${esc(T.endOfDoc)}</strong>${config.confidentiality ? inline(config.confidentiality) : ''}</footer>
348	</main></div>
349	${footer ? `<div class="print-footer">${esc(footer)} · ${esc(manual.program)} v${esc(version)}</div>` : ''}
350	<script type="application/json" id="manual-source">${embedJson({ manual, version })}</script>
351	<script type="application/json" id="editor-labels">${embedJson(editorLabels(manual.lang))}</script>
352	<script>${SCRIPT}</script>
353	${QUILL_JS ? `<script>${QUILL_JS}</script>` : ''}
354	<script>${EDITOR_SCRIPT}</script>
355	</body></html>
356	`;
357	}
358	
359	// ── Build ───────────────────────────────────────────────────────────────
360	
361	export function buildManual({ manualPath, outDir, sameVersion = false, major = false, cwd = process.cwd(), verbose = true }) {
362	  const manual = JSON.parse(readFileSync(manualPath, 'utf8'));
363	  // Screen theme: manual.json "theme", else the profile config "screenTheme", else Signature.
364	  if (manual.theme == null) manual.theme = readScreenTheme(cwd) ?? undefined;
365	  const lang = manual.lang || 'ko';
366	  const program = String(manual.program || 'PROGRAM');
367	  const dir = outDir || join(resolveArtifactBase(cwd), 'manuals');
368	  mkdirSync(join(dir, '_src'), { recursive: true });
369	
370	  const warnings = manualWarnings(manual);
371	  if (verbose) for (const w of warnings) console.log(`⚠ build-manual: ${w}`);
372	
373	  const cfg = readManualConfig(cwd);
374	  const config = { ...cfg.manual, ...(manual.meta || {}) };
375	  const historyPath = join(dir, `${slug(program)}-${lang}.history.json`);
376	  const history = existsSync(historyPath) ? JSON.parse(readFileSync(historyPath, 'utf8')) : { program, lang, versions: [] };
377	  const version = nextVersion(history, { sameVersion, major });
378	  const entry = { version, date: today(), author: config.author || '', note: manual.changeNote || '' };
379	  const versions = arr(history.versions);
380	  const previous = versions.at(-1)?.version === version ? versions.at(-2) : versions.at(-1);
381	  if (verbose && previous && entry.note && previous.note === entry.note) {
382	    console.log(`⚠ build-manual: changeNote "${entry.note}" repeats v${previous.version}'s note — describe what changed in v${version}`);
383	  }
384	  if (versions.at(-1)?.version === version) versions[versions.length - 1] = entry;
385	  else versions.push(entry);
386	  history.versions = versions;
387	
388	  const html = renderManualHtml(manual, { version, date: entry.date, config, history: versions });
389	  const htmlPath = join(dir, `${slug(program)}-v${version}-${lang}.html`);
390	  const sourcePath = join(dir, '_src', `${slug(program)}-v${version}-${lang}.manual.json`);
391	  writeFileSync(htmlPath, html, 'utf8');
392	  writeFileSync(sourcePath, readFileSync(manualPath, 'utf8'), 'utf8');
393	  writeFileSync(historyPath, `${JSON.stringify(history, null, 2)}\n`, 'utf8');
394	  if (verbose && !cfg.found && !manual.meta) console.log('⚠ build-manual: no "manual" block in config.json — cover shows no team / author / company (run manual-config.mjs set)');
395	  return { html: htmlPath, version, history: historyPath, source: sourcePath, warnings };
396	}
397	
398	/**
399	 * Reads the manual.json a user saved from the page's edit mode (embedded as
400	 * <script id="manual-source">) and writes it to `outPath`, so the next build keeps the edits.
401	 */
402	export function importEditedHtml(htmlPath, outPath) {
403	  const html = readFileSync(htmlPath, 'utf8');
404	  const m = /<script type="application\/json" id="manual-source">([\s\S]*?)<\/script>/.exec(html);
405	  if (!m) throw new Error(`${htmlPath} has no embedded manual source — was it saved from the page's edit mode?`);
406	  const { manual, version } = JSON.parse(m[1]);
407	  if (existsSync(outPath)) writeFileSync(`${outPath}.bak`, readFileSync(outPath));
408	  writeFileSync(outPath, `${JSON.stringify(manual, null, 2)}\n`, 'utf8');
409	  return { manual: outPath, fromVersion: version, edited: manual.edited || null, backup: existsSync(`${outPath}.bak`) ? `${outPath}.bak` : null };
410	}
411	
412	const thisFile = fileURLToPath(import.meta.url);
413	if (process.argv[1] && resolve(process.argv[1]) === thisFile && process.argv[2] === '--import') {
414	  const [, , , htmlPath, outPath] = process.argv;
415	  if (!htmlPath || !outPath) {
416	    console.error('Usage: node build-manual.mjs --import <edited.html> <manual.json to write>');
417	    process.exit(2);
418	  }
419	  try {
420	    console.log(JSON.stringify(importEditedHtml(resolve(htmlPath), resolve(outPath)), null, 2));
421	  } catch (e) {
422	    console.error(`build-manual: ${e.message}`);
423	    process.exit(1);
424	  }
425	} else if (process.argv[1] && resolve(process.argv[1]) === thisFile) {
426	  const args = process.argv.slice(2);
427	  let manualPath;
428	  let outDir;
429	  for (let i = 0; i < args.length; i++) {
430	    const a = args[i];
431	    if (a === '--out-dir') outDir = args[++i];
432	    else if (a.startsWith('--out-dir=')) outDir = a.slice('--out-dir='.length);
433	    else if (!a.startsWith('--')) manualPath = a;
434	  }
435	  if (!manualPath || (args.some(a => a.startsWith('--out-dir')) && !outDir)) {
436	    console.error('Usage: node build-manual.mjs <manual.json> [--out-dir DIR] [--same-version] [--major]');
437	    process.exit(2);
438	  }
439	  try {
440	    const result = buildManual({
441	      manualPath: resolve(manualPath),
442	      outDir: outDir ? resolve(outDir) : undefined,
443	      sameVersion: args.includes('--same-version'),
444	      major: args.includes('--major'),
445	    });
446	    console.log(JSON.stringify({ ...result, warnings: result.warnings.length }, null, 2));
447	  } catch (e) {
448	    console.error(`build-manual: ${e.message}`);
449	    process.exit(1);
450	  }
451	}
