455	    fig.setAttribute('data-callouts',JSON.stringify(marksOf(art._step)));
456	    if(window.sc4sapPlace)window.sc4sapPlace(fig);
457	  }
458	  function redrawCallouts(art){
459	    if(active&&art.contains(active))unmount();
460	    var st=art._step,ol=art.querySelector('ol.callouts');
461	    ol.innerHTML=(st.callouts||[]).map(function(c,i){
462	      var d=(c.details||[]).map(function(x,di){return '<li><span data-k="callouts.'+i+'.details.'+di+'">'+inline(x)+'</span></li>';}).join('');
463	      return '<li data-ci="'+i+'"><span class="num">'+(i+1)+'</span><div><span data-k="callouts.'+i+'.text">'+inline(c.text)+'</span>'+(d?'<ul>'+d+'</ul>':'')+'</div></li>';
464	    }).join('');
465	    editable(ol,true);addCalloutX(art);placeFig(art);
466	  }
467	  function addCallout(art){
468	    stepChange(art,function(){
469	      var st=art._step;st.callouts=st.callouts||[];
470	      var n=st.callouts.length;st.callouts.push({text:L.newCallout,pos:[24,24+n*26]});
471	      redrawCallouts(art);
472	    });
473	    var last=art.querySelector('ol.callouts>li:last-child [data-k]');
474	    if(last){if(Q)mount(last);else last.focus();}
475	  }
476	
477	  // ── screenshots ──
478	  function pickImage(art){
479	    var inp=document.createElement('input');inp.type='file';inp.accept='image/*';
480	    inp.addEventListener('change',function(){if(inp.files[0])useImage(art,inp.files[0]);});inp.click();
481	  }
482	  function useImage(art,file){
483	    var r=new FileReader();
484	    r.onload=function(){
485	      var img=new Image();
486	      img.onload=function(){
487	        stepChange(art,function(){
488	          var st=art._step;st.image={src:r.result,width:img.naturalWidth,height:img.naturalHeight};
489	          (st.callouts||[]).forEach(function(c,i){if(!c.pos)c.pos=[24,24+i*26];});
490	          var w=st.image.width,h=st.image.height;
491	          var svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'" style="max-width:'+w+'px"><image href="'+r.result+'" x="0" y="0" width="'+w+'" height="'+h+'"/></svg>';
492	          var fig=art.querySelector('figure.screen'),cap='<figcaption><span data-k="caption">'+inline(st.caption||'')+'</span></figcaption>';
493	          if(!fig){fig=document.createElement('figure');fig.className='screen';var body=art.querySelector('.step-body');body.insertBefore(fig,body.firstChild);body.classList.add('has-screen');}
494	          fig.setAttribute('data-image','');fig.innerHTML=svg+cap;editable(fig,true);
495	          refreshTools(art);placeFig(art);
496	        });
497	      };
498	      img.src=r.result;
499	    };
500	    r.readAsDataURL(file);
501	  }
502	  function restore(art){
503	    stepChange(art,function(){
504	      var st=art._step;delete st.image;
505	      var fig=art.querySelector('figure.screen');
506	      if(art._origFig){var tmp=document.createElement('div');tmp.innerHTML=art._origFig;var nf=tmp.firstChild;fig.replaceWith(nf);editable(nf,true);}
507	      else if(fig){fig.remove();art.querySelector('.step-body').classList.remove('has-screen');}
508	      refreshTools(art);placeFig(art);
509	    });
510	  }
511	
512	  // ── dragging a badge ──
513	  function svgPoint(svg,ev){var p=svg.createSVGPoint();p.x=ev.clientX;p.y=ev.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());}
514	  document.addEventListener('pointerdown',function(ev){
515	    if(!editing)return;
516	    var g=ev.target.closest&&ev.target.closest('.callout-badge');if(!g)return;
517	    var svg=g.ownerSVGElement,art=g.closest('article.step');if(!svg||!art)return;
518	    ev.preventDefault();
519	    var num=+g.getAttribute('data-num'),c=art._step.callouts[num-1];if(!c)return;
520	    var snap=snapshot(art),start=svgPoint(svg,ev),base=g.getAttribute('data-base'),o0=c.offset||[0,0],p0=c.pos||[0,0],moved=false;
521	    function mv(e){var p=svgPoint(svg,e);moved=true;g.setAttribute('transform','translate('+(p.x-start.x)+','+(p.y-start.y)+')');}
522	    function up(e){
523	      document.removeEventListener('pointermove',mv);document.removeEventListener('pointerup',up);
524	      if(!moved)return;
525	      var p=svgPoint(svg,e),dx=Math.round(p.x-start.x),dy=Math.round(p.y-start.y);
526	      if(base)c.offset=[o0[0]+dx,o0[1]+dy];else c.pos=[p0[0]+dx,p0[1]+dy];
527	      placeFig(art);mark();pushUndo(function(){restoreSnap(art,snap);});
528	    }
529	    document.addEventListener('pointermove',mv);document.addEventListener('pointerup',up);
530	  });
531	
532	  // ── keyboard, paste, selection ──
533	  function select(art){if(current)current.classList.remove('ed-current');current=art;art.classList.add('ed-current');}
534	  document.addEventListener('keydown',function(ev){
535	    if(!editing||!(ev.ctrlKey||ev.metaKey)||ev.shiftKey||String(ev.key).toLowerCase()!=='z')return;
536	    if(active&&active.contains(ev.target))return;          // Quill undoes inside the field
537	    if(ev.target.isContentEditable)return;                 // native undo inside the field
538	    ev.preventDefault();undo();
539	  });
540	  document.addEventListener('paste',function(ev){
541	    if(!editing)return;
542	    var items=(ev.clipboardData&&ev.clipboardData.items)||[];
543	    for(var i=0;i<items.length;i++){
544	      if(items[i].type.indexOf('image/')===0){
545	        var art=(ev.target.closest&&ev.target.closest('article.step'))||current;
546	        if(art){ev.preventDefault();ev.stopPropagation();useImage(art,items[i].getAsFile());}
547	        return;
548	      }
549	    }
550	    if(Q)return; // Quill keeps only bold / highlight / list from pasted text
551	    var e=ev.target.closest&&ev.target.closest(FIELDS);
552	    if(e){ev.preventDefault();document.execCommand('insertText',false,ev.clipboardData.getData('text/plain'));}
553	  },true);
554	
555	  // ── save ──
556	  function collect(){
557	    sections().forEach(function(sec){
558	      var si=+sec.getAttribute('data-si');
559	      M.scenarios[si].steps=articles(sec).map(function(a){return a._step;});
560	    });
561	    var un=(M.intro&&M.intro.unverified)||[];
562	    Object.keys(original).forEach(function(p){
563	      var now=getPath(M,p),i=un.indexOf(original[p]);
564	      if(i>=0&&now!==original[p]){un[i]=now;original[p]=now;}
565	    });
566	    tables().forEach(function(t){setPath(M,t.getAttribute('data-array'),rowsOf(t).map(function(tr){return tr._row;}));});
567	    M.edited={at:new Date().toISOString().slice(0,19).replace('T',' ')};
568	  }
569	  function pageHtml(){
570	    var doc=document.documentElement.cloneNode(true);
571	    doc.querySelectorAll('.ed-tools,.ed-x,.ed-rowtools,.ed-addrow,g.callout-layer,.ed-draft,.ed-guide').forEach(function(e){e.remove();});
572	    doc.querySelectorAll('table.ed-table').forEach(function(t){rowsOf(t).forEach(function(tr,i){tr.setAttribute('data-row',i);});});
573	    doc.querySelectorAll('[contenteditable]').forEach(function(e){e.removeAttribute('contenteditable');});
574	    doc.querySelectorAll('.ed-current').forEach(function(e){e.classList.remove('ed-current');});
575	    if(active){ // the field being edited: its text, not Quill's editor
576	      var live=[].slice.call(document.querySelectorAll(FIELDS)).indexOf(active);
577	      var copy=doc.querySelectorAll(FIELDS)[live];
578	      if(copy){copy.classList.remove('ed-quill','ql-container','ql-bubble');copy.innerHTML=inline(valueOf(active));}
579	    }
580	    doc.querySelectorAll('.step-note').forEach(function(p){var s=p.querySelector('[data-k]');if(s)p.hidden=!s.textContent.trim();});
581	    doc.querySelector('body').classList.remove('editing');
582	    var eb=doc.querySelector('#ed-bar');if(eb){eb.hidden=true;eb.innerHTML='';}
583	    var eBtn=doc.querySelector('#edit-btn');if(eBtn)eBtn.textContent=L.edit;
584	    doc.querySelector('#manual-source').textContent=JSON.stringify(SRC).replace(/</g,'\\u003c');
585	    return '<!doctype html>\n'+doc.outerHTML;
586	  }
587	  function fileName(){
588	    var f=decodeURIComponent((location.pathname.split('/').pop()||'manual.html'));
589	    return /-edited\.html$/i.test(f)?f:f.replace(/\.html?$/i,'')+'-edited.html';
590	  }
591	  function save(){
592	    collect();
593	    var html=pageHtml(),blob=new Blob([html],{type:'text/html'});
594	    function done(){dirty=false;clearTimeout(saveTimer);clearDraft();status(L.saved);}
595	    function download(){var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=fileName();document.body.appendChild(a);a.click();a.remove();done();}
596	    if(window.showSaveFilePicker){
597	      window.showSaveFilePicker({suggestedName:fileName(),types:[{description:'HTML',accept:{'text/html':['.html']}}]})
598	        .then(function(h){return h.createWritable();}).then(function(w){return w.write(blob).then(function(){return w.close();});}).then(done)
599	        .catch(function(e){if(e&&e.name!=='AbortError')download();});
600	    }else download();
601	  }
602	
603	  // ── bar, guide, on / off ──
604	  var undoBtn=null,statusEl=null;
605	  function status(t){if(statusEl)statusEl.textContent=t;}
606	  function refreshBar(){if(undoBtn)undoBtn.disabled=!undoStack.length;}
607	  function guide(){
608	    var o=document.createElement('div');o.className='ed-guide';
609	    var box=document.createElement('div'),h=document.createElement('h3'),ol=document.createElement('ol');
610	    h.textContent=L.guideTitle;L.guide.forEach(function(t){var li=document.createElement('li');li.textContent=t;ol.appendChild(li);});
611	    box.appendChild(h);box.appendChild(ol);box.appendChild(button(L.ok,function(){o.remove();}));
612	    o.appendChild(box);o.addEventListener('click',function(e){if(e.target===o)o.remove();});
613	    document.body.appendChild(o);
614	    try{localStorage.setItem(GUIDE_KEY,'1');}catch(e){}
615	  }
616	  function setEditing(on){
617	    prepare();
618	    if(!on&&active)unmount();
619	    editing=on;
620	    document.body.classList.toggle('editing',on);
621	    editable(document,on);
622	    btn.textContent=on?L.done:L.edit;
623	    bar.hidden=!on;
624	    if(on&&!bar.childNodes.length){
625	      statusEl=document.createElement('span');statusEl.className='status';
626	      undoBtn=button('↶ '+L.undo,undo);undoBtn.title='Ctrl+Z';
627	      var s=button(L.save,save);s.className='primary';
628	      bar.appendChild(statusEl);bar.appendChild(undoBtn);bar.appendChild(button('? '+L.help,guide));bar.appendChild(s);
629	      refreshBar();
630	    }
631	    document.querySelectorAll('figure.screen[data-zoom]').forEach(function(f){f.classList.remove('zoomed');});
632	    var seen=false;try{seen=!!localStorage.getItem(GUIDE_KEY);}catch(e){}
633	    if(on&&!seen)guide();
634	  }
635	  btn.addEventListener('click',function(){setEditing(!editing);});
636	  window.addEventListener('beforeunload',function(e){if(dirty){saveDraft();e.preventDefault();e.returnValue=L.unsaved;return L.unsaved;}});
637	  var resumed=false;try{resumed=sessionStorage.getItem(RESUME_KEY)===DRAFT_KEY;if(resumed)sessionStorage.removeItem(RESUME_KEY);}catch(e){}
638	  if(resumed){setEditing(true);dirty=true;}else offerDraft();
639	})();
640	`;
