        if (fwd) { var mx = (q1.x + q2.x) / 2; pts = [p1, { x: mx, y: p1.y }, { x: mx, y: p2.y }, p2]; }
        else { var dy = Math.max(a.b, b.b) + 24; pts = [p1, q1, { x: q1.x, y: dy }, { x: q2.x, y: dy }, q2, p2]; }
      } else {
        var x = s1 === 'E' ? Math.max(q1.x, q2.x) : Math.min(q1.x, q2.x);
