      var okA = (c2.x - p1.x) * DIR[s1][0] > 0, okB = (c2.y - p2.y) * DIR[s2][1] > 0;
      pts = okA && okB ? [p1, c2, p2] : [p1, q1, { x: q1.x, y: q2.y }, q2, p2];
