    var s = String(label || '');
    if (!s) return '#56657A';
    if (s === o.no || /^(no|n|아니오?|아니요|いいえ)\b/i.test(s)) return '#B0402F';
    if (s === o.yes || /^(yes|y|예|네|はい)\b/i.test(s)) return '#1E7A46';
    return '#56657A';
  }
