    var cx = p.x, cy = p.y, w = p.w, h = p.h, top = p.t;
    var y0 = cy - ((p.lines.length - 1) * LINE_H) / 2 + 4;
    function texts(fill, bold) {
      return p.lines.map(function (ln, i) {
