646	export function mdToHtml(markdown, { baseDir = process.cwd(), title, lang } = {}) {
647	  let text = String(markdown).replace(/^\uFEFF/, '').replace(/\r\n?/g, '\n');
648	  let pairs = [];
649	  const fm = text.match(/^---\n([\s\S]*?)\n---\n/);
650	  if (fm) {
651	    pairs = frontmatterPairs(fm[1]);
652	    text = text.slice(fm[0].length);
653	    const fmLang = fm[1].match(/^(?:lang|language):\s*["']?([A-Za-z-]+)/m);
654	    if (!lang && fmLang) lang = fmLang[1];
655	  }
656	  const labels = labelsFor(lang);
657	
658	  let lines = text.split('\n');
659	  const facts = findFacts(lines);
660	  if (facts) {
661	    pairs = [...pairs, ...facts.pairs];
662	    lines = [...lines.slice(0, facts.start), '<!-- sc4sap:facts -->', ...lines.slice(facts.end)];
663	  }
664	
665	  // Pass 1 learns the glossary and the section numbers; pass 2 renders with
666	  // them. Both walk the same lines in the same order, so table and heading
667	  // numbering agree.
668	  const found = new Map();
669	  found.sections = new Map();
670	  const base = { baseDir, labels, mermaid: false };
671	  const first = { ...base, title: '', ids: new Set(), tables: [], tableNo: 0, found, headings: [] };
672	  renderBlockList(lines, first);
673	  const ctx = {
674	    ...base, title: title || '', ids: new Set(), tables: first.tables, tableNo: 0,
675	    glossary: found, sectionIds: found.sections, headings: [],
676	  };
677	  const blocks = renderBlockList(lines, ctx);
678	
679	  const card = factsCard(pairs, ctx);
680	  const { hero, sections, audiences } = sectionize(blocks, card);
681	  const chips = chipsHtml(sections, labels);
682	  const heroHtml = hero.length || chips
683	    ? `<header class="hero">\n${hero.join('\n')}\n${chips}\n</header>`
684	    : '';
685	  const body = sections.map((s) =>
686	    `<section class="sec" aria-labelledby="${s.id}"${s.audience ? ` data-audience="${s.audience}"` : ''}>\n${s.parts.join('\n')}\n</section>`).join('\n');
687	
688	  const mermaid = ctx.mermaid
689	    ? `\n<script src="${MERMAID_CDN}"></script>\n<script>if(window.mermaid){var d=document.documentElement.dataset.theme||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');mermaid.initialize({startOnLoad:true,securityLevel:'strict',theme:d==='dark'?'dark':'default'});}</script>`
690	    : '';
691	  return `<!doctype html>
692	<html lang="${escapeHtml(lang || 'en')}">
693	<head>
694	<meta charset="utf-8">
695	<meta name="viewport" content="width=device-width, initial-scale=1">
696	<meta name="generator" content="sc4sap md-to-html">
697	<title>${escapeHtml(ctx.title || 'Document')}</title>
698	<style>${STYLE}</style>
699	</head>
700	<body>
701	<div class="layout">
702	${tocHtml(ctx.headings, audiences, labels)}
703	<main>
704	${heroHtml}
705	${body}
706	</main>
707	</div>
708	<script>var L=${JSON.stringify(labels).replace(/</g, '\\u003c')};${SCRIPT}</script>${mermaid}
709	</body>
710	</html>
711	`;
712	}
