// Glossary links: every glossary term (and the two halves of "용어 (Term)") found in
// the manual's prose becomes a dotted link to its glossary row, the meaning as tooltip —
// first occurrence per text field. Read from the glossary table itself, so the edit mode
// re-links after a change (window.sc4sapLinkTerms). No ${…} below; String.raw keeps backslashes.
export const LINK_SCRIPT = String.raw`
(function(){
  function terms(){
    var t=document.querySelector('#glossary table'),out=[];if(!t)return out;
    Array.prototype.slice.call(t.querySelectorAll('tbody>tr')).forEach(function(tr,i){
      var td=tr.querySelectorAll('td');if(td.length<2)return;
      var term=td[0].textContent.trim(),desc=td[1].textContent.trim();if(!term)return;
      tr.id='gl-'+(i+1);
      var vars=[term],m=/^(.+?)\s*[(（]([^)）]+)[)）]\s*$/.exec(term);
      if(m)vars.push(m[1].trim(),m[2].trim());
      vars.forEach(function(v){if(v.length>=2)out.push({v:v,key:v.toLowerCase(),id:tr.id,desc:desc});});
    });
    return out.sort(function(a,b){return b.v.length-a.v.length;});
  }
  function esc(s){return s.replace(/[.*+?^$(){}|[\]\\]/g,'\\$&');}
  function unlink(root){
    Array.prototype.slice.call(root.querySelectorAll('a.gl')).forEach(function(a){a.replaceWith(document.createTextNode(a.textContent));});
    root.normalize();
  }
  function link(){
    var main=document.querySelector('main');if(!main)return;
    unlink(main);
    var list=terms();if(!list.length)return;
    var byKey={};list.forEach(function(t){if(!byKey[t.key])byKey[t.key]=t;});
    var re=new RegExp(list.map(function(t){return /^[A-Za-z0-9 _-]+$/.test(t.v)?'\\b'+esc(t.v)+'\\b':esc(t.v);}).join('|'),'gi');
    main.querySelectorAll('[data-p],[data-k],[data-l]').forEach(function(f){
      if(f.closest('#glossary,h1,h2,h3,h4,.cover,.ed-quill'))return;
      var seen={},walker=document.createTreeWalker(f,NodeFilter.SHOW_TEXT,null),nodes=[],n;
      while((n=walker.nextNode()))if(!n.parentNode.closest('code,a'))nodes.push(n);
      nodes.forEach(function(node){
        var s=node.nodeValue,last=0,m,frag=null;re.lastIndex=0;
        while((m=re.exec(s))){
          var t=byKey[m[0].toLowerCase()];if(!t||seen[t.id])continue;
          seen[t.id]=1;frag=frag||document.createDocumentFragment();
          frag.appendChild(document.createTextNode(s.slice(last,m.index)));
          var a=document.createElement('a');a.className='gl';a.href='#'+t.id;a.title=t.desc;a.textContent=m[0];frag.appendChild(a);
          last=m.index+m[0].length;
        }
        if(frag){frag.appendChild(document.createTextNode(s.slice(last)));node.replaceWith(frag);}
      });
    });
  }
  window.sc4sapLinkTerms=link;
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',link);else link();
})();
`;

