content.content:
140	// the manual's prose becomes a dotted link to its glossary row, the meaning as tooltip —
141	// first occurrence per step, check-point box or section. Read from the glossary table itself, so the edit mode
142	// re-links after a change (window.sc4sapLinkTerms). No ${…} below; String.raw keeps backslashes.
143	export const LINK_SCRIPT = String.raw`
144	(function(){
145	  function terms(){
146	    var t=document.querySelector('#glossary table'),out=[];if(!t)return out;
147	    Array.prototype.slice.call(t.querySelectorAll('tbody>tr')).forEach(function(tr,i){
148	      var td=tr.querySelectorAll('td');if(td.length<2)return;
149	      var term=td[0].textContent.trim(),desc=td[1].textContent.trim();if(!term)return;
150	      tr.id='gl-'+(i+1);
151	      var vars=[term],m=/^(.+?)\s*[(（]([^)）]+)[)）]\s*$/.exec(term);
152	      if(m)vars.push(m[1].trim(),m[2].trim());
153	      vars.forEach(function(v){if(v.length>=2)out.push({v:v,key:v.toLowerCase(),id:tr.id,desc:desc});});
154	    });
155	    return out.sort(function(a,b){return b.v.length-a.v.length;});
156	  }
157	  function esc(s){return s.replace(/[.*+?^$(){}|[\]\\]/g,'\\$&');}
158	  function unlink(root){
159	    Array.prototype.slice.call(root.querySelectorAll('a.gl')).forEach(function(a){a.replaceWith(document.createTextNode(a.textContent));});
160	    root.normalize();
161	  }
162	  function link(){
163	    var main=document.querySelector('main');if(!main)return;
164	    unlink(main);
165	    var list=terms();if(!list.length)return;
166	    var byKey={};list.forEach(function(t){if(!byKey[t.key])byKey[t.key]=t;});
167	    var re=new RegExp(list.map(function(t){return /^[A-Za-z0-9 _-]+$/.test(t.v)?'\\b'+esc(t.v)+'\\b':esc(t.v);}).join('|'),'gi');
168	    var seenIn=new Map(); // one link per term per step / check-point box / section
169	    main.querySelectorAll('[data-p],[data-k],[data-l]').forEach(function(f){
170	      if(f.closest('#glossary,h1,h2,h3,h4,.cover,.ed-quill'))return;
171	      var box=f.closest('article.step,aside,section')||main;
172	      if(!seenIn.has(box))seenIn.set(box,{});
173	      var seen=seenIn.get(box),walker=document.createTreeWalker(f,NodeFilter.SHOW_TEXT,null),nodes=[],n;
174	      while((n=walker.nextNode()))if(!n.parentNode.closest('code,a'))nodes.push(n);
175	      nodes.forEach(function(node){
176	        var s=node.nodeValue,last=0,m,frag=null;re.lastIndex=0;
177	        while((m=re.exec(s))){
178	          var t=byKey[m[0].toLowerCase()];if(!t||seen[t.id])continue;
