387	export function buildManual({ manualPath, outDir, sameVersion = false, major = false, cwd = process.cwd(), verbose = true }) {
388	  const manual = JSON.parse(readFileSync(manualPath, 'utf8'));
389	  // Screen theme: manual.json "theme", else the profile config "screenTheme", else Signature.
390	  if (manual.theme == null) manual.theme = readScreenTheme(cwd) ?? undefined;
391	  const lang = manual.lang || 'ko';
392	  const program = String(manual.program || 'PROGRAM');
393	  const dir = outDir || join(resolveArtifactBase(cwd), 'manuals');
394	  mkdirSync(join(dir, '_src'), { recursive: true });
395	
396	  const warnings = manualWarnings(manual);
397	  if (verbose) for (const w of warnings) console.log(`⚠ build-manual: ${w}`);
398	
399	  const cfg = readManualConfig(cwd);
400	  const config = { ...cfg.manual, ...(manual.meta || {}) };
401	  const historyPath = join(dir, `${slug(program)}-${lang}.history.json`);
402	  const history = existsSync(historyPath) ? JSON.parse(readFileSync(historyPath, 'utf8')) : { program, lang, versions: [] };
403	  const version = nextVersion(history, { sameVersion, major });
404	  const entry = { version, date: today(), author: config.author || '', note: manual.changeNote || '' };
405	  const versions = arr(history.versions);
406	  const previous = versions.at(-1)?.version === version ? versions.at(-2) : versions.at(-1);
407	  if (verbose && previous && entry.note && previous.note === entry.note) {
408	    console.log(`⚠ build-manual: changeNote "${entry.note}" repeats v${previous.version}'s note — describe what changed in v${version}`);
409	  }
410	  if (versions.at(-1)?.version === version) versions[versions.length - 1] = entry;
411	  else versions.push(entry);
412	  history.versions = versions;
413	
414	  const html = renderManualHtml(manual, { version, date: entry.date, config, history: versions });
415	  const htmlPath = join(dir, `${slug(program)}-v${version}-${lang}.html`);
416	  const sourcePath = join(dir, '_src', `${slug(program)}-v${version}-${lang}.manual.json`);
417	  writeFileSync(htmlPath, html, 'utf8');
418	  writeFileSync(sourcePath, readFileSync(manualPath, 'utf8'), 'utf8');
419	  writeFileSync(historyPath, `${JSON.stringify(history, null, 2)}\n`, 'utf8');
420	  if (verbose && !cfg.found && !manual.meta) console.log('⚠ build-manual: no "manual" block in config.json — cover shows no team / author / company (run manual-config.mjs set)');
421	  return { html: htmlPath, version, history: historyPath, source: sourcePath, warnings };
422	}
