431	  if (!m) throw new Error(`${htmlPath} has no embedded manual source — was it saved from the page's edit mode?`);
432	  const { manual, version } = JSON.parse(m[1]);
433	  if (existsSync(outPath)) writeFileSync(`${outPath}.bak`, readFileSync(outPath));
434	  writeFileSync(outPath, `${JSON.stringify(manual, null, 2)}\n`, 'utf8');
435	  return { manual: outPath, fromVersion: version, edited: manual.edited || null, backup: existsSync(`${outPath}.bak`) ? `${outPath}.bak` : null };
