439	if (process.argv[1] && resolve(process.argv[1]) === thisFile && process.argv[2] === '--import') {
440	  const [, , , htmlPath, outPath] = process.argv;
441	  if (!htmlPath || !outPath) {
442	    console.error('Usage: node build-manual.mjs --import <edited.html> <manual.json to write>');
443	    process.exit(2);
