451	} else if (process.argv[1] && resolve(process.argv[1]) === thisFile) {
452	  const args = process.argv.slice(2);
453	  let manualPath;
454	  let outDir;
455	  for (let i = 0; i < args.length; i++) {
456	    const a = args[i];
457	    if (a === '--out-dir') outDir = args[++i];
